BEGIN;

CREATE FUNCTION pg_temp.expect_ok(t text, q text) RETURNS void AS $$
BEGIN
  EXECUTE q;
  RAISE NOTICE 'PASS (accepted): %', t;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'FAIL (should be accepted): % -> %', t, SQLERRM;
END $$ LANGUAGE plpgsql;

CREATE FUNCTION pg_temp.expect_fail(t text, q text) RETURNS void AS $$
BEGIN
  EXECUTE q;
  RAISE NOTICE 'FAIL (should be rejected): %', t;
EXCEPTION WHEN OTHERS THEN
  RAISE NOTICE 'PASS (rejected): % -> %', t, left(SQLERRM, 80);
END $$ LANGUAGE plpgsql;

DO $$
DECLARE
  admin_id int; arjun int; priya int; dev int;
  case41 int; case57 int;
  ravi int; sita int; kiran int;
  ig int; tg int; ig_posts int; ig_followers int; tg_messages int;
  acc_ravi_ig int; acc_sita_ig int;
  pan1 int; pan2 int; sess int;
BEGIN
  -- ---------- valid data ----------
  INSERT INTO users(email,password_hash,full_name,role) VALUES ('v_meera@x.in','h','Meera','admin') RETURNING user_id INTO admin_id;
  INSERT INTO users(email,password_hash,full_name,role) VALUES ('v_arjun@x.in','h','Arjun','examiner') RETURNING user_id INTO arjun;
  INSERT INTO users(email,password_hash,full_name,role) VALUES ('v_priya@x.in','h','Priya','reviewer') RETURNING user_id INTO priya;
  INSERT INTO users(email,password_hash,full_name,role) VALUES ('v_dev@x.in','h','Dev','examiner') RETURNING user_id INTO dev;
  INSERT INTO cases(case_number,title,description,created_by) VALUES ('V-041','Case 41','desc',admin_id) RETURNING case_id INTO case41;
  INSERT INTO cases(case_number,title,created_by) VALUES ('V-057','Case 57',admin_id) RETURNING case_id INTO case57;
  INSERT INTO case_assignments(case_id,user_id) VALUES (case41,arjun),(case41,priya),(case57,arjun);
  INSERT INTO suspects(full_name,aadhar_number) VALUES ('Ravi','999988887777') RETURNING suspect_id INTO ravi;
  INSERT INTO suspects(full_name) VALUES ('Sita') RETURNING suspect_id INTO sita;
  INSERT INTO suspects(full_name) VALUES ('Kiran') RETURNING suspect_id INTO kiran;
  PERFORM pg_temp.expect_ok('one suspect linked to TWO cases', format($f$INSERT INTO case_suspects(case_id,suspect_id,involvement) VALUES (%s,%s,'suspect'),(%s,%s,'accused')$f$,case41,ravi,case57,ravi));
  INSERT INTO case_suspects(case_id,suspect_id,involvement) VALUES (case41,sita,'suspect');
  INSERT INTO platforms(platform_name) VALUES ('v_instagram') RETURNING platform_id INTO ig;
  INSERT INTO platforms(platform_name) VALUES ('v_telegram') RETURNING platform_id INTO tg;
  INSERT INTO platform_sections(platform_id,section_name) VALUES (ig,'posts') RETURNING platform_section_id INTO ig_posts;
  INSERT INTO platform_sections(platform_id,section_name) VALUES (ig,'followers') RETURNING platform_section_id INTO ig_followers;
  INSERT INTO platform_sections(platform_id,section_name) VALUES (tg,'messages') RETURNING platform_section_id INTO tg_messages;
  INSERT INTO social_accounts(suspect_id,platform_id,handle) VALUES (ravi,ig,'ravi_ig') RETURNING account_id INTO acc_ravi_ig;
  INSERT INTO social_accounts(suspect_id,platform_id,handle) VALUES (sita,ig,'sita_ig') RETURNING account_id INTO acc_sita_ig;
  PERFORM pg_temp.expect_ok('two accounts with NULL platform_account_id', format($f$INSERT INTO social_accounts(suspect_id,platform_id,handle) VALUES (%s,%s,'kiran_a'),(%s,%s,'kiran_b')$f$,kiran,ig,kiran,tg));
  INSERT INTO panchnamas(panchnama_no,case_id,examiner_id,authority_ref,location,held_at) VALUES ('V-P1',case41,arjun,'W1','Delhi',now()) RETURNING panchnama_id INTO pan1;
  INSERT INTO panchnamas(panchnama_no,case_id,examiner_id,authority_ref,location,held_at) VALUES ('V-P2',case57,arjun,'W2','Delhi',now()) RETURNING panchnama_id INTO pan2;
  INSERT INTO capture_sessions(panchnama_id,account_id,device_type,tool_version) VALUES (pan1,acc_ravi_ig,'macos','0.1') RETURNING session_id INTO sess;
  PERFORM pg_temp.expect_ok('screenshot with a section of the right platform', format($f$INSERT INTO screenshots(session_id,platform_section_id,sequence_no,file_path,sha256_hash) VALUES (%s,%s,1,'/f',repeat('a',64))$f$,sess,ig_posts));
  PERFORM pg_temp.expect_ok('same witness in two panchnamas', format($f$INSERT INTO witnesses(panchnama_id,full_name,aadhar_number) VALUES (%s,'W','111122223333'),(%s,'W','111122223333')$f$,pan1,pan2));
  PERFORM pg_temp.expect_ok('report generated by examiner, approved by reviewer', format($f$INSERT INTO reports(panchnama_id,file_path,sha256_hash,generated_by,approved_by,approved_at) VALUES (%s,'/r',repeat('b',64),%s,%s,now())$f$,pan1,arjun,priya));
  PERFORM pg_temp.expect_ok('audit row with no user (failed login)', $f$INSERT INTO audit_logs(action,chain_hash) VALUES ('LOGIN_FAILED',repeat('d',64))$f$);

  -- ---------- must be rejected ----------
  PERFORM pg_temp.expect_fail('duplicate email', $f$INSERT INTO users(email,password_hash,full_name,role) VALUES ('v_arjun@x.in','h','x','admin')$f$);
  PERFORM pg_temp.expect_fail('case with a creator that does not exist', $f$INSERT INTO cases(case_number,title,created_by) VALUES ('V-9','t',-1)$f$);
  PERFORM pg_temp.expect_fail('case with NULL title', format($f$INSERT INTO cases(case_number,title,created_by) VALUES ('V-8',NULL,%s)$f$,admin_id));
  PERFORM pg_temp.expect_fail('device_type android', format($f$INSERT INTO capture_sessions(panchnama_id,account_id,device_type,tool_version) VALUES (%s,%s,'android','0.1')$f$,pan1,acc_ravi_ig));
  PERFORM pg_temp.expect_fail('panchnama by an examiner NOT assigned to the case', format($f$INSERT INTO panchnamas(panchnama_no,case_id,examiner_id,authority_ref,location,held_at) VALUES ('V-P3',%s,%s,'W','x',now())$f$,case41,dev));
  PERFORM pg_temp.expect_fail('panchnama by an assigned user who is a reviewer', format($f$INSERT INTO panchnamas(panchnama_no,case_id,examiner_id,authority_ref,location,held_at) VALUES ('V-P4',%s,%s,'W','x',now())$f$,case41,priya));
  PERFORM pg_temp.expect_fail('same suspect linked twice to the same case', format($f$INSERT INTO case_suspects(case_id,suspect_id,involvement) VALUES (%s,%s,'suspect')$f$,case41,ravi));
  PERFORM pg_temp.expect_fail('duplicate (suspect, platform, handle)', format($f$INSERT INTO social_accounts(suspect_id,platform_id,handle) VALUES (%s,%s,'ravi_ig')$f$,ravi,ig));
  PERFORM pg_temp.expect_fail('session: account''s suspect not linked to the panchnama''s case', format($f$INSERT INTO capture_sessions(panchnama_id,account_id,device_type,tool_version) VALUES (%s,%s,'ios','0.1')$f$,pan2,acc_sita_ig));
  PERFORM pg_temp.expect_fail('session ends before it starts', format($f$INSERT INTO capture_sessions(panchnama_id,account_id,device_type,tool_version,started_at,ended_at) VALUES (%s,%s,'ios','0.1',now(),now()-interval '1 day')$f$,pan1,acc_ravi_ig));
  PERFORM pg_temp.expect_fail('screenshot section from another platform', format($f$INSERT INTO screenshots(session_id,platform_section_id,sequence_no,file_path,sha256_hash) VALUES (%s,%s,2,'/f',repeat('a',64))$f$,sess,tg_messages));
  PERFORM pg_temp.expect_fail('screenshot duplicate sequence', format($f$INSERT INTO screenshots(session_id,platform_section_id,sequence_no,file_path,sha256_hash) VALUES (%s,%s,1,'/f2',repeat('a',64))$f$,sess,ig_posts));
  PERFORM pg_temp.expect_fail('report approved by its own generator', format($f$INSERT INTO reports(panchnama_id,version_no,file_path,sha256_hash,generated_by,approved_by,approved_at) VALUES (%s,5,'/r',repeat('b',64),%s,%s,now())$f$,pan1,priya,priya));
  PERFORM pg_temp.expect_fail('report approved_by set but approved_at empty', format($f$INSERT INTO reports(panchnama_id,version_no,file_path,sha256_hash,generated_by,approved_by) VALUES (%s,6,'/r',repeat('b',64),%s,%s)$f$,pan1,arjun,priya));
  PERFORM pg_temp.expect_fail('report approved by an examiner', format($f$INSERT INTO reports(panchnama_id,version_no,file_path,sha256_hash,generated_by,approved_by,approved_at) VALUES (%s,7,'/r',repeat('b',64),%s,%s,now())$f$,pan1,priya,dev));
  PERFORM pg_temp.expect_fail('report duplicate version', format($f$INSERT INTO reports(panchnama_id,version_no,file_path,sha256_hash,generated_by) VALUES (%s,1,'/r',repeat('b',64),%s)$f$,pan1,arjun));
  PERFORM pg_temp.expect_fail('suspect aadhar with 11 digits', $f$INSERT INTO suspects(full_name,aadhar_number) VALUES ('B','12345678901')$f$);
  PERFORM pg_temp.expect_fail('suspect aadhar duplicate', $f$INSERT INTO suspects(full_name,aadhar_number) VALUES ('B','999988887777')$f$);
  PERFORM pg_temp.expect_fail('witness aadhar with letters', format($f$INSERT INTO witnesses(panchnama_id,full_name,aadhar_number) VALUES (%s,'W','12345678901a')$f$,pan1));
  PERFORM pg_temp.expect_fail('witness duplicate aadhar in the same panchnama', format($f$INSERT INTO witnesses(panchnama_id,full_name,aadhar_number) VALUES (%s,'W2','111122223333')$f$,pan1));
  PERFORM pg_temp.expect_fail('audit entity_type without entity_id', $f$INSERT INTO audit_logs(action,entity_type,chain_hash) VALUES ('X','report',repeat('d',64))$f$);
  PERFORM pg_temp.expect_fail('delete a user that is referenced', format('DELETE FROM users WHERE user_id=%s',arjun));
  PERFORM pg_temp.expect_fail('delete a case that is referenced', format('DELETE FROM cases WHERE case_id=%s',case41));
  PERFORM pg_temp.expect_fail('audit_logs UPDATE', $f$UPDATE audit_logs SET action='HACK'$f$);
  PERFORM pg_temp.expect_fail('audit_logs DELETE', $f$DELETE FROM audit_logs$f$);
  PERFORM pg_temp.expect_fail('audit_logs TRUNCATE', $f$TRUNCATE audit_logs$f$);
END $$;

ROLLBACK;
